module TdpBram (
  input  logic clk,
  input  logic [10:0] port_a_addr,
  input  logic port_a_en,
  output logic [15:0] port_a_rdata,
  input  logic [10:0] port_b_addr,
  input  logic [15:0] port_b_wdata,
  input  logic port_b_we,
  input  logic port_b_en,
  output logic [15:0] port_b_rdata
);
  (* ram_style = "block" *)
  logic [15:0] mem [0:2047];
  initial begin
    $readmemh("system_image.hex", mem);
  end

  logic [15:0] port_a_rdata_raw;
  logic [15:0] port_a_rdata_raw;
  logic [15:0] port_b_rdata_raw;

  always_ff @(posedge clk) begin
    if (port_a_en) begin
      port_a_rdata_raw <= mem[port_a_addr];
    end
    port_a_rdata <= port_a_rdata_raw;
  end

  always_ff @(posedge clk) begin
    if (port_b_en) begin
      if (port_b_we) begin
        mem[port_b_addr] <= port_b_wdata;
        port_b_rdata_raw <= port_b_wdata;
      end else begin
        port_b_rdata_raw <= mem[port_b_addr];
      end
    end
    port_b_rdata <= port_b_rdata_raw;
  end
endmodule


