always_ff @(posedge clk) begin
  if(reset) begin
      tx_busy_latch <= 1'h0;
  end   else begin
      if(txd_strobe) begin
          tx_busy_latch <= 1'h1;
      end       else begin
          if(txd_ready) begin
              tx_busy_latch <= 1'h0;
          end 

      end 

  end 

end

assign cpu_tx_status = tx_busy_latch ? 16'h1 : 16'h0;  // mux
endmodule : Ulx3sTop